-- Source-reviewed 2022 systems questions and exact 2021 July repeats.
INSERT OR IGNORE INTO questions (id,track_id,topic,difficulty,question_type,prompt,options_json,answer_json,explanation,source_type,source_reference,language,exam_section,exam_section_method,question_kind,exam_origin) VALUES
('fe-exempt-2022-20221211-q14','exam-fe','メモリインタリーブ','standard','single_choice','【IPA 2022年度 修了認定試験 2022-12-11 問14・改編】メモリインタリーブの説明として適切なものはどれか。','[{"id":"a","text":"CPUからのアクセス高速化のためキャッシュと主記憶へ同時に書き込む"},{"id":"b","text":"主記憶を複数のバンクに分け並列アクセスして高速化する"},{"id":"c","text":"CPUと主記憶の速度差を埋める高速小容量メモリを配置する"},{"id":"d","text":"パイプラインを乱さないためキャッシュを命令用とデータ用に分離する"}]','"b"','主記憶を複数バンクに分け、アクセスを並行させる方式。 中文：内存交叉存取将主存划分为多个存储体并并行访问。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20221211_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2022-20221211-q15','exam-fe','3層クライアントサーバ','standard','single_choice','【IPA 2022年度 修了認定試験 2022-12-11 問15・改編】3層クライアントサーバシステムの各層の役割として適切なものはどれか。','[{"id":"a","text":"データベースアクセス層がデータを加工してプレゼンテーション層へ返す"},{"id":"b","text":"ファンクション層がデータベースアクセス層のSQL文を解釈する"},{"id":"c","text":"ファンクション層がデータを加工してプレゼンテーション層へ返す"},{"id":"d","text":"プレゼンテーション層がデータベースアクセス層へSQLで問い合わせる"}]','"c"','ファンクション層は業務処理やデータ加工を担い、その結果を表示側へ返す。 中文：功能层负责业务处理与数据加工，再将结果返回表示层。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20221211_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2022-20221211-q16','exam-fe','仮想化と縮退運転','standard','single_choice','【IPA 2022年度 修了認定試験 2022-12-11 問16・改編】物理マシン20台で仮想マシンを運用する。停止したマシンの仮想マシンと使用資源は残りの全マシンへ均等配分する。20台稼働時の使用率は各70%、1台の使用率が90%を超えるとシステム全体が縮退運転となる。少なくとも何台が停止すると縮退運転になるか。','[{"id":"a","text":"2"},{"id":"b","text":"3"},{"id":"c","text":"4"},{"id":"d","text":"5"}]','"d"','使用資源は計20×0.7=14台分。4台停止なら14/16=87.5%、5台停止なら14/15≈93.3%で90%を超える。 中文：总负载相当于14台；停4台为87.5%，停5台约93.3%。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20221211_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2022-20221211-q17','exam-fe','並行処理','standard','single_choice','【IPA 2022年度 修了認定試験 2022-12-11 問17・改編】共有変数xの初期値は3。タスクAはa1:xをeに読む、a2:xをfに読む、a3:e+fをgに計算、a4:gをxに書く。タスクBはb1:xをhに読む、b2:xをiに読む、b3:h×iをjに計算、b4:jをxに書く。同期なしで最終x=12となる順序はどれか。','[{"id":"a","text":"a1→a2→b1→b2→a3→a4→b3→b4"},{"id":"b","text":"a1→b1→b2→b3→b4→a2→a3→a4"},{"id":"c","text":"b1→a1→a2→a3→a4→b2→b3→b4"},{"id":"d","text":"b1→b2→b3→a1→a2→a3→a4→b4"}]','"b"','イではAが先に3を読み、Bが3×3=9を書いた後にAが9を読み、3+9=12を書く。 中文：A先读3，B写入9，A再读9并写入3+9=12。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20221211_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2022-20221211-q18','exam-fe','メモリリーク','standard','single_choice','【IPA 2022年度 修了認定試験 2022-12-11 問18・改編】メモリリークの説明として適切なものはどれか。','[{"id":"a","text":"バグなどで確保した主記憶が解放されず、利用可能な領域が減る"},{"id":"b","text":"同時実行数の増加でページングが大半を占め、スループットが極端に低下する"},{"id":"c","text":"実行時の領域制限下で必要になったモジュールを主記憶へ取り込む"},{"id":"d","text":"空き領域の合計は足りるが不連続に散在し、大きな連続領域を確保できない"}]','"a"','不要になったメモリが解放されず利用可能領域が減ること。 中文：内存泄漏指已分配但不再使用的内存未释放，导致可用内存减少。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20221211_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2022-20221211-q20','exam-fe','リトルエンディアン','standard','single_choice','【IPA 2022年度 修了認定試験 2022-12-11 問20・改編】16進数ABCD1234をリトルエンディアン方式で4バイトのメモリに配置する。バイトアドレスのオフセット0、+1、+2、+3の順に並べたものはどれか。','[{"id":"a","text":"12 34 AB CD"},{"id":"b","text":"34 12 CD AB"},{"id":"c","text":"43 21 DC BA"},{"id":"d","text":"AB CD 12 34"}]','"b"','下位バイトを低いアドレスへ置くため、34、12、CD、ABの順。バイト内のビットや桁順は反転しない。 中文：小端序将最低字节放在最低地址，顺序为34、12、CD、AB。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20221211_FE.pdf','ja','A','explicit','standard','fe_exemption');
